const { SlashCommandBuilder, AttachmentBuilder } = require("discord.js");
const { CommandInteraction, Client } = require("discord.js");
const Canvas = require("@napi-rs/canvas");
/**
 * Add image to image
 * @param {string|Buffer} image
 * @param {string} type
 * @returns {Promise<Buffer>}
 */
async function skel(image, type) {
  if (!image) throw new Error("image was not provided!");

  let spooky = await Canvas.loadImage(type);
  let img = await Canvas.loadImage(image);
  const canvas = Canvas.createCanvas(img.width, img.height);
  const ctx = canvas.getContext("2d");
  ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
  ctx.drawImage(
    spooky,
    canvas.width / 2 - 50,
    canvas.height / 2,
    canvas.width,
    canvas.height,
  );
  return canvas.encode("png");
}

let skeleton = {
  image: {
    mime: "image/png",
    data: "",
  },
};
let rover = {
  image: {
    mime: "image/png",
    data: "",
  },
};

let timmy = {
  image: {
    mime: "image/webp",
    data: "",
  },
};
let cow = {
  image: {
    mime: "image/png",
    data: "",
  },
};
let mtndew = {
  image: {
    mime: "image/png",
    data: "",
  },
};

const overlayImages = { skeleton, rover, timmy, cow, mtndew };

module.exports = {
  data: new SlashCommandBuilder()
    .setName("add-image")
    .setDescription("[IMG] puts the chosen image on a user's pfp")
    .addUserOption((option) =>
      option.setName("user").setDescription("who?").setRequired(true),
    )
    .addStringOption((option) =>
      option
        .setName("type")
        .setDescription("Image you want to add")
        .addChoices(
          {
            name: "skeleton",
            value: "skeleton",
          },
          {
            name: "rover",
            value: "rover",
          },
          {
            name: "timmy",
            value: "timmy",
          },
          {
            name: "cow",
            value: "cow",
          },
          {
            name: "mtndew",
            value: "mtndew",
          },
        )
        .setRequired(true),
    ),
  /**
   * Executes the command
   * @param {CommandInteraction} interaction
   * @param {Client} client
   * @param {*} config
   * @param {*} dbContext
   * @param {Array} allowed
   */
  async execute(interaction, client, config, db, allowed) {
    let msg = interaction;
    let user = interaction.options.getUser("user");
    let type = interaction.options.getString("type");
    await msg.deferReply();

    const overlay = overlayImages[type];
    if (!overlay) {
      return msg.editReply("❌ Unknown overlay selected.");
    }

    let av = user.displayAvatarURL({ size: 512 });
    const overlaySrc = `data:${overlay.image.mime};base64,${overlay.image.data}`;

    let image = await skel(av, overlaySrc);
    let file = new AttachmentBuilder(image, {
      name: `${user.tag}-addimg.png`,
    });

    msg.editReply({ files: [file] });
  },
};
